//! PL011 Linux module host-build proof.
//!
//! Proves that the PL011 Linux artifact set generated by the canonical Regseq
//! compiler emission path builds cleanly as an out-of-tree module against the
//! owned evaluation kernel.
//!
//! This proof:
//!
//! - emits PL011 artifacts via the production `EmitSpec::Driver` path through
//!   `RUSTC_WRAPPER` (the same path used by `cargo regseq`)
//! - cross-compiles the generated module against the pinned v6.18.21 arm64
//!   kernel tree
//! - verifies the `.ko` is produced
//! - runs `modinfo` on the built module
//! - proves freshness by hashing all source files before and after build
//! - retains build logs and evidence for reviewer inspection
//!
//! All tests are `#[ignore]` because they require:
//!
//! - cross-compiler: `aarch64-linux-gnu-gcc`
//! - kernel tree: `~/regseq-eval/pl011/kernel-src/pl011-arm64-linux`
//! - `modinfo` (kmod)
//!
//! Run with:
//!
//! ```sh
//! cargo test -p regseq-e2e --test pl011_linux_module_host_build_proof -- --ignored
//! ```

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::process::Command;

// ---------------------------------------------------------------------------
// Helpers: paths
// ---------------------------------------------------------------------------

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .parent()
        .unwrap()
        .to_path_buf()
}

fn fixture_path() -> PathBuf {
    workspace_root().join("tests/fixtures/pl011-full-spec")
}

fn output_root() -> PathBuf {
    workspace_root().join("output/linux/pl011-full-spec")
}

fn kernel_dir() -> PathBuf {
    let home = std::env::var("HOME").expect("HOME must be set");
    let kdir = PathBuf::from(home).join("regseq-eval/pl011/kernel-src/pl011-arm64-linux");
    assert!(
        kdir.join("Module.symvers").exists(),
        "Kernel tree at {} must be pre-built (Module.symvers not found)",
        kdir.display()
    );
    kdir
}

// ---------------------------------------------------------------------------
// Helpers: toolchain detection (same as pl011_spec_slice.rs)
// ---------------------------------------------------------------------------

fn build_driver() -> PathBuf {
    let status = Command::new("cargo")
        .args(["build", "-p", "regseq-driver"])
        .current_dir(workspace_root())
        .status()
        .expect("failed to run cargo build");
    assert!(status.success(), "cargo build -p regseq-driver failed");

    workspace_root().join("target/debug/regseq-driver")
}

fn detect_sysroot() -> String {
    let output = Command::new("rustc")
        .args(["--print", "sysroot"])
        .output()
        .expect("failed to run rustc --print sysroot");
    assert!(output.status.success());
    String::from_utf8(output.stdout)
        .expect("sysroot not utf-8")
        .trim()
        .to_string()
}

fn detect_host() -> String {
    let output = Command::new("rustc")
        .arg("-vV")
        .output()
        .expect("failed to run rustc -vV");
    assert!(output.status.success());
    let stdout = String::from_utf8(output.stdout).expect("not utf-8");
    stdout
        .lines()
        .find_map(|line| line.strip_prefix("host: "))
        .expect("missing host line")
        .trim()
        .to_string()
}

// ---------------------------------------------------------------------------
// Helpers: emission
// ---------------------------------------------------------------------------

fn make_options_json() -> String {
    let platform_file = fixture_path().join("platform.toml");
    let output_dir = output_root();
    serde_json::json!({
        "target_os": "linux",
        "platform_file": platform_file,
        "output_dir": output_dir,
        "emit": [{"type": "driver", "match_id": null}],
        "check": false,
        "add_analysis": [],
        "skip_analysis": [],
        "deny": [],
        "allow": [],
        "params": [],
        "log_level": "warn",
        "dump_stage": null,
        "color": "auto"
    })
    .to_string()
}

/// Emission context: captures the exact command and environment for evidence.
struct EmissionContext {
    driver_path: String,
    sysroot: String,
    host: String,
    options_json: String,
    fixture: PathBuf,
    fixture_target: PathBuf,
}

/// Run canonical emission via RUSTC_WRAPPER, returning (success, stderr) and
/// the emission context for evidence capture.
fn run_emission() -> (bool, String, EmissionContext) {
    let out = output_root();
    if out.exists() {
        std::fs::remove_dir_all(&out).expect("failed to clean output directory");
    }

    let driver = build_driver();
    let sysroot = detect_sysroot();
    let host = detect_host();
    let options_json = make_options_json();
    let fixture = fixture_path();
    let fixture_target = fixture.join("target");

    let output = Command::new("cargo")
        .arg("check")
        .arg("--target")
        .arg(&host)
        .arg("--color")
        .arg("never")
        .env("RUSTC_WRAPPER", &driver)
        .env("REGSEQ_OPTIONS", &options_json)
        .env("REGSEQ_SYSROOT", &sysroot)
        .env("CARGO_TARGET_DIR", &fixture_target)
        .current_dir(&fixture)
        .output()
        .expect("failed to run cargo check with regseq-driver");

    let stderr = String::from_utf8_lossy(&output.stderr).to_string();
    let success = output.status.success();

    let ctx = EmissionContext {
        driver_path: driver.display().to_string(),
        sysroot,
        host,
        options_json,
        fixture: fixture.clone(),
        fixture_target,
    };

    (success, stderr, ctx)
}

// ---------------------------------------------------------------------------
// Helpers: hashing and build
// ---------------------------------------------------------------------------

fn hash_source_files(dir: &Path) -> HashMap<String, u64> {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::Hasher;

    let mut hashes = HashMap::new();
    if let Ok(entries) = std::fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_file() {
                let name = path.file_name().unwrap().to_string_lossy().to_string();
                let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
                if ext == "c" || ext == "h" || name == "Makefile" || name == "Kbuild" {
                    let content = std::fs::read(&path).unwrap();
                    let mut hasher = DefaultHasher::new();
                    hasher.write(&content);
                    hashes.insert(name, hasher.finish());
                }
            }
        }
    }
    hashes
}

fn run_kernel_build(module_dir: &Path, kdir: &Path) -> (bool, String, String) {
    let output = Command::new("make")
        .arg("-C")
        .arg(kdir)
        .arg(format!("M={}", module_dir.display()))
        .arg("ARCH=arm64")
        .arg("CROSS_COMPILE=aarch64-linux-gnu-")
        .arg("modules")
        .output()
        .expect("failed to run make");

    let success = output.status.success();
    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();
    (success, stdout, stderr)
}

fn run_modinfo(ko_path: &Path) -> (bool, String) {
    let output = Command::new("modinfo")
        .arg(ko_path)
        .output()
        .expect("failed to run modinfo");

    let success = output.status.success();
    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    (success, stdout)
}

fn write_proof_log(content: &str) {
    let path = output_root().join("proof-log.txt");
    std::fs::write(&path, content)
        .unwrap_or_else(|e| panic!("failed to write proof log to {}: {e}", path.display()));
}

// ---------------------------------------------------------------------------
// Test: emission produces expected artifacts
// ---------------------------------------------------------------------------

#[test]
#[ignore]
fn emission_produces_expected_artifacts() {
    let (success, stderr, _ctx) = run_emission();
    assert!(success, "Emission failed. stderr:\n{stderr}");
    assert!(
        stderr.contains("driver emission complete"),
        "Expected 'driver emission complete' in stderr, got:\n{stderr}"
    );

    let out = output_root();
    let expected_files = [
        "regseq_pl011_full_spec_module.c",
        "regseq_pl011_full_spec_shared.h",
        "pl011_full_spec_regs.h",
        "Makefile",
        "Kbuild",
    ];

    for name in &expected_files {
        let path = out.join(name);
        assert!(path.exists(), "Expected file not found: {}", path.display());
        let meta = std::fs::metadata(&path).unwrap();
        assert!(meta.len() > 0, "File is empty: {}", path.display());
    }
}

// ---------------------------------------------------------------------------
// Test: emission is deterministic
// ---------------------------------------------------------------------------

#[test]
#[ignore]
fn emission_is_deterministic() {
    let (success1, stderr1, _) = run_emission();
    assert!(success1, "First emission failed:\n{stderr1}");
    let hashes1 = hash_source_files(&output_root());

    let (success2, stderr2, _) = run_emission();
    assert!(success2, "Second emission failed:\n{stderr2}");
    let hashes2 = hash_source_files(&output_root());

    assert_eq!(
        hashes1, hashes2,
        "Emission is not deterministic: file hashes differ between runs"
    );
}

// ---------------------------------------------------------------------------
// Test: full host-build proof
// ---------------------------------------------------------------------------

#[test]
#[ignore]
fn pl011_host_build_proof() {
    // ---- Phase 1: Emission ----
    let (emission_ok, emission_stderr, ctx) = run_emission();
    let out = output_root();
    let kdir = kernel_dir();

    // ---- Phase 2: Generated file manifest ----
    let mut file_manifest = String::new();
    if out.exists() {
        if let Ok(entries) = std::fs::read_dir(&out) {
            let mut files: Vec<_> = entries.flatten().collect();
            files.sort_by_key(|e| e.file_name());
            for entry in &files {
                let meta = entry.metadata().unwrap();
                file_manifest.push_str(&format!(
                    "  {} ({} bytes)\n",
                    entry.file_name().to_string_lossy(),
                    meta.len()
                ));
            }
        }
    }

    // ---- Phase 3: Pre-build source hashes ----
    let pre_build_hashes = hash_source_files(&out);

    // ---- Phase 4: Host build ----
    let (build_ok, build_stdout, build_stderr) = if emission_ok {
        run_kernel_build(&out, &kdir)
    } else {
        (false, String::new(), "skipped: emission failed".into())
    };

    // ---- Phase 5: .ko and modinfo ----
    let ko_path = out.join("regseq_pl011_full_spec_module.ko");
    let ko_exists = ko_path.exists();

    let (modinfo_ok, modinfo_output) = if ko_exists {
        run_modinfo(&ko_path)
    } else {
        (false, "skipped: .ko not found".into())
    };

    // ---- Phase 6: Post-build source hashes ----
    let post_build_hashes = hash_source_files(&out);
    let freshness_pass = pre_build_hashes == post_build_hashes;

    // ---- Phase 7: Write proof log (before assertions) ----
    let mut log = String::new();
    log.push_str("=== PL011 Linux Module Host-Build Proof ===\n\n");

    log.push_str("-- Emission command --\n");
    log.push_str(&format!("  RUSTC_WRAPPER={}\n", ctx.driver_path));
    log.push_str(&format!("  REGSEQ_SYSROOT={}\n", ctx.sysroot));
    log.push_str(&format!(
        "  CARGO_TARGET_DIR={}\n",
        ctx.fixture_target.display()
    ));
    log.push_str(&format!("  REGSEQ_OPTIONS={}\n", ctx.options_json));
    log.push_str(&format!(
        "  cargo check --target {} --color never\n",
        ctx.host
    ));
    log.push_str(&format!("  (working dir: {})\n", ctx.fixture.display()));

    log.push_str(&format!(
        "\n-- Emission result: {} --\n",
        if emission_ok { "SUCCESS" } else { "FAILED" }
    ));

    log.push_str("\n-- Host build command --\n");
    log.push_str(&format!(
        "  make -C {} M={} ARCH=arm64 CROSS_COMPILE=aarch64-linux-gnu- modules\n",
        kdir.display(),
        out.display()
    ));

    log.push_str("\n-- Generated files --\n");
    log.push_str(&file_manifest);

    log.push_str("\n-- Source hashes (pre-build) --\n");
    let mut pre_keys: Vec<_> = pre_build_hashes.keys().collect();
    pre_keys.sort();
    for name in &pre_keys {
        log.push_str(&format!("  {}: {:016x}\n", name, pre_build_hashes[*name]));
    }

    log.push_str("\n-- Source hashes (post-build) --\n");
    let mut post_keys: Vec<_> = post_build_hashes.keys().collect();
    post_keys.sort();
    for name in &post_keys {
        log.push_str(&format!("  {}: {:016x}\n", name, post_build_hashes[*name]));
    }

    log.push_str(&format!(
        "\n-- Freshness: {} --\n",
        if freshness_pass {
            "PASS (no source modifications)"
        } else {
            "FAIL (sources modified between emission and build)"
        }
    ));

    log.push_str(&format!("\n-- Kernel tree --\n  {}\n", kdir.display()));

    log.push_str(&format!(
        "\n-- Build result: {} --\n",
        if build_ok { "SUCCESS" } else { "FAILED" }
    ));

    log.push_str(&format!(
        "\n-- Build log --\n=== stdout ===\n{build_stdout}\n=== stderr ===\n{build_stderr}\n"
    ));

    log.push_str(&format!(
        "\n-- .ko path --\n  {}\n",
        if ko_exists {
            ko_path.display().to_string()
        } else {
            "ABSENT".into()
        }
    ));

    log.push_str(&format!("\n-- modinfo output --\n{modinfo_output}\n"));

    log.push_str(&format!("\n-- Emission stderr --\n{emission_stderr}\n"));

    write_proof_log(&log);

    // ---- Phase 8: Assertions ----
    assert!(
        emission_ok,
        "Emission failed. See proof-log.txt for details.\n{emission_stderr}"
    );
    assert!(
        build_ok,
        "Host build failed. See proof-log.txt for build log.\n=== stderr ===\n{build_stderr}"
    );
    assert!(
        ko_exists,
        ".ko not found at {}. See proof-log.txt.",
        ko_path.display()
    );
    assert!(
        modinfo_ok,
        "modinfo failed on {}. See proof-log.txt.",
        ko_path.display()
    );
    assert!(
        freshness_pass,
        "Source files were modified between emission and build. See proof-log.txt."
    );
}
